-- People P3-A (docs/people-leave-p3.md): leave types, leave policies, policy revisions and the
-- effective-dated assignment of a policy to an employee. Generated by `prisma migrate diff`, then the
-- constraints, guards, partial indexes, grants and RLS Prisma cannot express were added by hand (section
-- marked "hand-written"). Wrapped in one transaction (docs/migration-readiness.md §7, STAB-M6).
--
-- Ordering: depends on 20261118000000_people (people_employees, the PE SQLSTATE codes). It changes no
-- existing table, column or row; it adds four tables. It sorts after Finance F7-A
-- (20261130000000_finance_catalog, newest on main) and Communications E1
-- (20261129000000_communications_erasure, open PR 64) and depends on neither. No privileged SQL.
--
-- Configuration only: no leave requests, approvals or balances (P3-B, P3-C). No entitlement is derived
-- from a country; every number is entered by the business.
--
-- SQLSTATEs (class PE, people; PE001-PE008 are P1's):
--   PE004 identity, leave type or unit changed; revision or assignment rewritten
--   PE006 policy assigned to a terminated employee     PE007 archived leave type or policy referenced
--   PE008 archiving a leave type or policy in use       PE009 version must advance by exactly one
--   PE010 an archived leave type or policy is read-only PE011 assignment overlaps the employee's history
--   PE012 an inactive policy cannot be newly assigned
BEGIN;
-- CreateTable
CREATE TABLE "people_leave_types" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "category" TEXT NOT NULL,
    "paid" BOOLEAN NOT NULL,
    "sensitive" BOOLEAN NOT NULL DEFAULT false,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "archived_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "people_leave_types_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "people_leave_policies" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "leave_type_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "country_code" CHAR(2),
    "unit" TEXT NOT NULL,
    "granularity" TEXT NOT NULL,
    "entitlement_method" TEXT NOT NULL,
    "entitlement_amount" DECIMAL(9,4),
    "accrual_frequency" TEXT,
    "year_start" TEXT,
    "year_start_month" SMALLINT,
    "year_start_day" SMALLINT,
    "carryover" TEXT NOT NULL DEFAULT 'NONE',
    "carryover_cap" DECIMAL(9,4),
    "max_balance" DECIMAL(9,4),
    "negative_balance_limit" DECIMAL(9,4) NOT NULL DEFAULT 0,
    "requires_approval" BOOLEAN NOT NULL DEFAULT true,
    "minimum_notice_days" INTEGER,
    "allow_backdated" BOOLEAN NOT NULL DEFAULT false,
    "waiting_period_days" INTEGER,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "archived_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "people_leave_policies_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "people_leave_policy_revisions" (
    "business_id" UUID NOT NULL,
    "policy_id" UUID NOT NULL,
    "version" INTEGER NOT NULL,
    "rules" JSONB NOT NULL,
    "recorded_by_id" UUID,
    "recorded_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "people_leave_policy_revisions_pkey" PRIMARY KEY ("policy_id","version")
);

-- CreateTable
CREATE TABLE "people_leave_policy_assignments" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "employee_id" UUID NOT NULL,
    "leave_type_id" UUID NOT NULL,
    "policy_id" UUID NOT NULL,
    "starts_on" DATE NOT NULL,
    "ends_on" DATE,
    "created_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ended_by_id" UUID,
    "ended_at" TIMESTAMPTZ,

    CONSTRAINT "people_leave_policy_assignments_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "people_leave_types_business_id_name_id_idx" ON "people_leave_types"("business_id", "name", "id");

-- CreateIndex
CREATE UNIQUE INDEX "people_leave_types_business_id_id_key" ON "people_leave_types"("business_id", "id");

