ALTER TABLE "people_leave_policies" ADD CONSTRAINT "people_leave_policies_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "people_leave_policies" ADD CONSTRAINT "people_leave_policies_leave_type_fkey" FOREIGN KEY ("business_id", "leave_type_id") REFERENCES "people_leave_types"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "people_leave_policy_revisions" ADD CONSTRAINT "people_leave_policy_revisions_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "people_leave_policy_revisions" ADD CONSTRAINT "people_leave_policy_revisions_policy_fkey" FOREIGN KEY ("business_id", "policy_id") REFERENCES "people_leave_policies"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "people_leave_policy_assignments" ADD CONSTRAINT "people_leave_policy_assignments_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

