ALTER TABLE "people_leave_policy_assignments" ADD CONSTRAINT "people_leave_policy_assignments_employee_fkey" FOREIGN KEY ("business_id", "employee_id") REFERENCES "people_employees"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

