ALTER TABLE "people_leave_policy_assignments" ADD CONSTRAINT "people_leave_policy_assignments_leave_type_fkey" FOREIGN KEY ("business_id", "leave_type_id") REFERENCES "people_leave_types"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

