ALTER TABLE "people_leave_policy_assignments" ADD CONSTRAINT "people_leave_policy_assignments_policy_fkey" FOREIGN KEY ("business_id", "policy_id", "leave_type_id") REFERENCES "people_leave_policies"("business_id", "id", "leave_type_id") ON DELETE NO ACTION ON UPDATE NO ACTION;


-- ---------------------------------------------------------------------------------------------
-- hand-written: constraints, name uniqueness, guards, revisions, least privilege and RLS.

ALTER TABLE "people_leave_types"
  ADD CONSTRAINT people_leave_types_name_length CHECK (char_length(btrim("name")) BETWEEN 1 AND 120 AND char_length("name") <= 120),
  ADD CONSTRAINT people_leave_types_description_length CHECK ("description" IS NULL OR char_length("description") <= 2000),
  ADD CONSTRAINT people_leave_types_category CHECK ("category" IN ('ANNUAL', 'SICK', 'PERSONAL', 'CARER', 'UNPAID', 'COMPASSIONATE', 'PARENTAL', 'STUDY', 'OTHER')),
  ADD CONSTRAINT people_leave_types_status CHECK ("status" IN ('ACTIVE', 'INACTIVE')),
  ADD CONSTRAINT people_leave_types_version_positive CHECK ("version" >= 1);

ALTER TABLE "people_leave_policies"
  ADD CONSTRAINT people_leave_policies_name_length CHECK (char_length(btrim("name")) BETWEEN 1 AND 120 AND char_length("name") <= 120),
  ADD CONSTRAINT people_leave_policies_description_length CHECK ("description" IS NULL OR char_length("description") <= 2000),
  ADD CONSTRAINT people_leave_policies_country CHECK ("country_code" IS NULL OR "country_code" ~ '^[A-Z]{2}$'),
  ADD CONSTRAINT people_leave_policies_unit CHECK ("unit" IN ('DAYS', 'HOURS')),
  ADD CONSTRAINT people_leave_policies_granularity CHECK (
    ("unit" = 'DAYS' AND "granularity" IN ('FULL_DAY', 'HALF_DAY')) OR ("unit" = 'HOURS' AND "granularity" IN ('HOUR', 'HALF_HOUR', 'QUARTER_HOUR'))),
  ADD CONSTRAINT people_leave_policies_method CHECK ("entitlement_method" IN ('NONE', 'GRANT', 'ACCRUAL')),
  -- A balance is kept (GRANT, ACCRUAL) exactly when there is an amount and a leave year.
  ADD CONSTRAINT people_leave_policies_amount CHECK (
    ("entitlement_method" = 'NONE') = ("entitlement_amount" IS NULL) AND ("entitlement_amount" IS NULL OR "entitlement_amount" > 0)),
  ADD CONSTRAINT people_leave_policies_accrual CHECK (
    ("entitlement_method" = 'ACCRUAL') = ("accrual_frequency" IS NOT NULL)
    AND ("accrual_frequency" IS NULL OR "accrual_frequency" IN ('WEEKLY', 'FORTNIGHTLY', 'MONTHLY'))),
  ADD CONSTRAINT people_leave_policies_year CHECK (
    ("entitlement_method" = 'NONE') = ("year_start" IS NULL) AND ("year_start" IS NULL OR "year_start" IN ('CALENDAR', 'ANNIVERSARY', 'CUSTOM'))),
  -- A custom leave year starts on a day that exists every year (no 29 February).
  ADD CONSTRAINT people_leave_policies_year_custom CHECK (
    ("year_start" IS NOT DISTINCT FROM 'CUSTOM') = ("year_start_month" IS NOT NULL)
    AND ("year_start_month" IS NULL) = ("year_start_day" IS NULL)
    AND ("year_start_month" IS NULL OR ("year_start_month" BETWEEN 1 AND 12
         AND "year_start_day" BETWEEN 1 AND CASE WHEN "year_start_month" = 2 THEN 28 WHEN "year_start_month" IN (4, 6, 9, 11) THEN 30 ELSE 31 END))),
  ADD CONSTRAINT people_leave_policies_carryover CHECK (
    "carryover" IN ('NONE', 'UNLIMITED', 'CAPPED')
    AND ("entitlement_method" <> 'NONE' OR "carryover" = 'NONE')
    AND ("carryover" = 'CAPPED') = ("carryover_cap" IS NOT NULL)
    AND ("carryover_cap" IS NULL OR "carryover_cap" >= 0)),
  ADD CONSTRAINT people_leave_policies_max_balance CHECK (
    "max_balance" IS NULL OR ("max_balance" > 0 AND "entitlement_method" <> 'NONE')),
  ADD CONSTRAINT people_leave_policies_negative CHECK (
    "negative_balance_limit" >= 0 AND ("entitlement_method" <> 'NONE' OR "negative_balance_limit" = 0)),
  ADD CONSTRAINT people_leave_policies_notice CHECK ("minimum_notice_days" IS NULL OR "minimum_notice_days" BETWEEN 0 AND 365),
  ADD CONSTRAINT people_leave_policies_waiting CHECK ("waiting_period_days" IS NULL OR "waiting_period_days" BETWEEN 0 AND 3650),
  ADD CONSTRAINT people_leave_policies_status CHECK ("status" IN ('ACTIVE', 'INACTIVE')),
  ADD CONSTRAINT people_leave_policies_version_positive CHECK ("version" >= 1);

ALTER TABLE "people_leave_policy_revisions"
  ADD CONSTRAINT people_leave_policy_revisions_version_positive CHECK ("version" >= 1);

ALTER TABLE "people_leave_policy_assignments"
  ADD CONSTRAINT people_leave_policy_assignments_dates CHECK ("ends_on" IS NULL OR "ends_on" >= "starts_on"),
  ADD CONSTRAINT people_leave_policy_assignments_ended CHECK (("ends_on" IS NULL) = ("ended_at" IS NULL));

-- Names of current (not archived) types and policies are unique per business, ignoring case and
-- surrounding spaces, as for departments and locations.
CREATE UNIQUE INDEX "people_leave_types_active_name_key" ON "people_leave_types" ("business_id", lower(btrim("name"))) WHERE "archived_at" IS NULL;
CREATE UNIQUE INDEX "people_leave_policies_active_name_key" ON "people_leave_policies" ("business_id", lower(btrim("name"))) WHERE "archived_at" IS NULL;
-- At most one current policy per employee and leave type.
CREATE UNIQUE INDEX "people_leave_policy_assignments_open_key" ON "people_leave_policy_assignments" ("business_id", "employee_id", "leave_type_id") WHERE "ends_on" IS NULL;

-- ---- leave types --------------------------------------------------------------------------------
-- Identity fixed; times stamped by the database; the version advances by exactly one; an archived type
-- is read-only except for its restore, and an archive changes nothing else. Archiving is refused while
-- the type has a policy that is not archived: the row lock this UPDATE holds conflicts with the
-- FOR SHARE a policy insert or restore takes on its type, so the check sees every such policy.
CREATE FUNCTION people_leave_types_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.archived_at IS NOT NULL OR NEW.version <> 1 THEN
      RAISE EXCEPTION 'a leave type is created unarchived at version 1' USING ERRCODE = 'PE004';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.business_id <> OLD.business_id OR NEW.created_at <> OLD.created_at OR NEW.created_by_id IS DISTINCT FROM OLD.created_by_id THEN
    RAISE EXCEPTION 'a leave type''s identity is fixed' USING ERRCODE = 'PE004';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'a leave type''s version advances by one on every change' USING ERRCODE = 'PE009';
  END IF;
  IF (NEW.name, NEW.description, NEW.category, NEW.paid, NEW.sensitive, NEW.status)
     IS DISTINCT FROM (OLD.name, OLD.description, OLD.category, OLD.paid, OLD.sensitive, OLD.status)
     AND (OLD.archived_at IS NOT NULL OR NEW.archived_at IS NOT NULL) THEN
    RAISE EXCEPTION 'an archived leave type is read-only, and archiving changes nothing else' USING ERRCODE = 'PE010';
  END IF;
  IF OLD.archived_at IS NOT NULL AND NEW.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'an archived leave type is read-only' USING ERRCODE = 'PE010';
  END IF;
  IF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM people_leave_policies WHERE business_id = NEW.business_id AND leave_type_id = NEW.id AND archived_at IS NULL) THEN
      RAISE EXCEPTION 'leave type has policies that are not archived' USING ERRCODE = 'PE008';
    END IF;
    NEW.archived_at := now();
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_types_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_types_guard BEFORE INSERT OR UPDATE ON "people_leave_types"
  FOR EACH ROW EXECUTE FUNCTION people_leave_types_guard();

-- ---- leave policies -----------------------------------------------------------------------------
-- As for types, plus: the leave type and the unit are fixed (a balance in days never becomes one in
-- hours); a policy is created or restored only under a type that is not archived (FOR SHARE on the
-- type, so a concurrent archive of the type either commits first or waits); archiving is refused while
-- an employee is currently assigned (the row lock conflicts with the FOR SHARE every assignment takes).
CREATE FUNCTION people_leave_policies_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.archived_at IS NOT NULL OR NEW.version <> 1 THEN
      RAISE EXCEPTION 'a leave policy is created unarchived at version 1' USING ERRCODE = 'PE004';
    END IF;
    NEW.created_at := now();
  ELSE
    IF NEW.id <> OLD.id OR NEW.business_id <> OLD.business_id OR NEW.leave_type_id <> OLD.leave_type_id OR NEW.unit <> OLD.unit
       OR NEW.created_at <> OLD.created_at OR NEW.created_by_id IS DISTINCT FROM OLD.created_by_id THEN
      RAISE EXCEPTION 'a leave policy''s identity, leave type and unit are fixed' USING ERRCODE = 'PE004';
    END IF;
    IF NEW.version <> OLD.version + 1 THEN
      RAISE EXCEPTION 'a leave policy''s version advances by one on every change' USING ERRCODE = 'PE009';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['archived_at', 'version', 'updated_by_id', 'updated_at'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['archived_at', 'version', 'updated_by_id', 'updated_at'])
       AND (OLD.archived_at IS NOT NULL OR NEW.archived_at IS NOT NULL) THEN
      RAISE EXCEPTION 'an archived leave policy is read-only, and archiving changes nothing else' USING ERRCODE = 'PE010';
    END IF;
    IF OLD.archived_at IS NOT NULL AND NEW.archived_at IS NOT NULL THEN
      RAISE EXCEPTION 'an archived leave policy is read-only' USING ERRCODE = 'PE010';
    END IF;
    IF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM people_leave_policy_assignments WHERE business_id = NEW.business_id AND policy_id = NEW.id AND ends_on IS NULL) THEN
        RAISE EXCEPTION 'leave policy is assigned' USING ERRCODE = 'PE008';
      END IF;
      NEW.archived_at := now();
    END IF;
  END IF;
  IF TG_OP = 'INSERT' OR (OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL) THEN
    PERFORM 1 FROM people_leave_types WHERE business_id = NEW.business_id AND id = NEW.leave_type_id AND archived_at IS NULL FOR SHARE;
    -- A missing type (or another business's, invisible under RLS) on insert is left to the composite FK.
    IF NOT FOUND AND (TG_OP = 'UPDATE' OR EXISTS (SELECT 1 FROM people_leave_types WHERE business_id = NEW.business_id AND id = NEW.leave_type_id)) THEN
      RAISE EXCEPTION 'leave type is archived' USING ERRCODE = 'PE007';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_policies_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_policies_guard BEFORE INSERT OR UPDATE ON "people_leave_policies"
  FOR EACH ROW EXECUTE FUNCTION people_leave_policies_guard();

-- ---- policy revisions ---------------------------------------------------------------------------
-- Every insert and update of a policy appends the rules it now holds, under its new version. The
-- revision guard derives the row from the policy itself (the rules, who changed it, when), so a
-- revision can only ever state what the policy really was at that version; it cannot be written ahead
-- of the policy, rewritten or deleted.
CREATE FUNCTION people_leave_policy_rules(p people_leave_policies) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT to_jsonb(p) - ARRAY['id', 'business_id', 'version', 'created_by_id', 'updated_by_id', 'created_at', 'updated_at']
$$;
REVOKE ALL ON FUNCTION people_leave_policy_rules(people_leave_policies) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION people_leave_policy_rules(people_leave_policies) TO bos_app;

CREATE FUNCTION people_leave_policy_revisions_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  p people_leave_policies;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'policy revisions are append-only' USING ERRCODE = 'PE004';
  END IF;
  SELECT * INTO p FROM people_leave_policies WHERE business_id = NEW.business_id AND id = NEW.policy_id;
  IF NOT FOUND OR p.version <> NEW.version THEN
    RAISE EXCEPTION 'a revision records the policy''s current version' USING ERRCODE = 'PE004';
  END IF;
  NEW.rules := people_leave_policy_rules(p);
  NEW.recorded_by_id := p.updated_by_id;
  NEW.recorded_at := now();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_policy_revisions_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_policy_revisions_guard BEFORE INSERT OR UPDATE ON "people_leave_policy_revisions"
  FOR EACH ROW EXECUTE FUNCTION people_leave_policy_revisions_guard();

CREATE FUNCTION people_leave_policies_record() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  INSERT INTO people_leave_policy_revisions (business_id, policy_id, version, rules)
  VALUES (NEW.business_id, NEW.id, NEW.version, '{}'::jsonb);
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION people_leave_policies_record() FROM PUBLIC;
CREATE TRIGGER people_leave_policies_record AFTER INSERT OR UPDATE ON "people_leave_policies"
  FOR EACH ROW EXECUTE FUNCTION people_leave_policies_record();

-- ---- policy assignments -------------------------------------------------------------------------
-- Created open and closed exactly once; nothing else changes. A new row needs an employee who is not
-- terminated (FOR SHARE on the employee, so a termination racing it either commits first or waits) and
-- an active, unarchived policy (FOR SHARE, against a racing archive). It may not overlap any earlier row
-- for the same employee and leave type: the service closes the current row first, at the same date.
CREATE FUNCTION people_leave_policy_assignments_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  employee_status text;
  policy_status text;
  policy_archived timestamptz;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.ends_on IS NOT NULL OR NEW.ends_on IS NULL
       OR (to_jsonb(NEW) - ARRAY['ends_on', 'ended_at', 'ended_by_id']) <> (to_jsonb(OLD) - ARRAY['ends_on', 'ended_at', 'ended_by_id']) THEN
      RAISE EXCEPTION 'assignments are closed once and otherwise immutable' USING ERRCODE = 'PE004';
    END IF;
    NEW.ended_at := now();
    RETURN NEW;
  END IF;
  IF NEW.ends_on IS NOT NULL OR NEW.ended_at IS NOT NULL OR NEW.ended_by_id IS NOT NULL THEN
    RAISE EXCEPTION 'assignments are created open' USING ERRCODE = 'PE004';
  END IF;
  NEW.created_at := now();
  SELECT p.status, p.archived_at INTO policy_status, policy_archived FROM people_leave_policies p
   WHERE p.business_id = NEW.business_id AND p.id = NEW.policy_id FOR SHARE;
  IF FOUND AND policy_archived IS NOT NULL THEN
    RAISE EXCEPTION 'leave policy is archived' USING ERRCODE = 'PE007';
  END IF;
  IF FOUND AND policy_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'leave policy is inactive' USING ERRCODE = 'PE012';
  END IF;
  SELECT e.status::text INTO employee_status FROM people_employees e
   WHERE e.business_id = NEW.business_id AND e.id = NEW.employee_id FOR SHARE;
  IF employee_status = 'TERMINATED' THEN
    RAISE EXCEPTION 'employee is terminated' USING ERRCODE = 'PE006';
  END IF;
  IF EXISTS (SELECT 1 FROM people_leave_policy_assignments a
              WHERE a.business_id = NEW.business_id AND a.employee_id = NEW.employee_id AND a.leave_type_id = NEW.leave_type_id
                AND (a.ends_on IS NULL OR a.ends_on > NEW.starts_on)) THEN
    RAISE EXCEPTION 'assignment overlaps an earlier one' USING ERRCODE = 'PE011';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_policy_assignments_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_policy_assignments_guard BEFORE INSERT OR UPDATE ON "people_leave_policy_assignments"
  FOR EACH ROW EXECUTE FUNCTION people_leave_policy_assignments_guard();

-- ---- least privilege ----------------------------------------------------------------------------
-- No DELETE or TRUNCATE on any leave table. Identity, type, unit and creation columns are not updatable
-- at all; revisions are insert-only (and derived by their guard); assignments may only be closed.
REVOKE ALL ON "people_leave_types", "people_leave_policies", "people_leave_policy_revisions", "people_leave_policy_assignments" FROM bos_app;
GRANT SELECT, INSERT ON "people_leave_types", "people_leave_policies", "people_leave_policy_revisions", "people_leave_policy_assignments" TO bos_app;
GRANT UPDATE ("name", "description", "category", "paid", "sensitive", "status", "archived_at", "version", "updated_by_id", "updated_at")
  ON "people_leave_types" TO bos_app;
GRANT UPDATE ("name", "description", "country_code", "granularity", "entitlement_method", "entitlement_amount", "accrual_frequency", "year_start",
              "year_start_month", "year_start_day", "carryover", "carryover_cap", "max_balance", "negative_balance_limit", "requires_approval",
              "minimum_notice_days", "allow_backdated", "waiting_period_days", "status", "archived_at", "version", "updated_by_id", "updated_at")
  ON "people_leave_policies" TO bos_app;
